import React, { useState } from "react";

function App() {
  const [resultados, setResultados] = useState(null);

  const subirArchivos = async (e) => {
    const files = e.target.files;
    const formData = new FormData();
    for (let f of files) formData.append("files", f);

    const res = await fetch("http://localhost:4000/upload", {
      method: "POST",
      body: formData
    });

    const data = await res.json();
    setResultados(data);
  };

  return (
    <div style={{ padding: 40, fontFamily: "Arial" }}>
      <h1>Calculadora IVA XML CR</h1>
      <p>Suba sus archivos XML</p>

      <input type="file" multiple accept=".xml" onChange={subirArchivos} />

      {resultados && (
        <div style={{ marginTop: 40 }}>
          <h2>Resultados:</h2>

          {Object.entries(resultados).map(([tarifa, valores]) => (
            <div key={tarifa} style={{ marginBottom: 20 }}>
              <h3>⚡ IVA {tarifa}</h3>
              <p><strong>Monto Base:</strong> ₡{valores.base.toLocaleString()}</p>
              <p><strong>IVA:</strong> ₡{valores.iva.toLocaleString()}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default App;
